-- public.svc_reserve_payment / svc_attach_payment_intent / svc_release_payment
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;
create function pg_temp.login(u uuid) returns void language plpgsql as $f$ begin
  perform set_config('request.jwt.claims', json_build_object('sub', u, 'role', 'authenticated')::text, true);
  perform set_config('role', 'authenticated', true); end $f$;
create function pg_temp.anon() returns void language plpgsql as $f$ begin
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  perform set_config('role', 'anon', true); end $f$;

-- Events: e1 Team A absorb $45 (Ava, Ben, Teen); e2 Team A pass_on $25 (Ava); e3 club-issued $30 (Ava, Ben);
-- e4 Team A DRAFT; e5 Team B $20 (Cleo) on an account that cannot take charges yet.

reset role; select pg_temp.login('a2222222-2222-2222-2222-222222222222');
select throws_ok($$ select public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b1000000-0000-0000-0000-000000000001']::uuid[]) $$, '42501', null, 'clients cannot call the service-role reservation');
reset role;
select is((public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b1000000-0000-0000-0000-000000000001']::uuid[]) ->> 'reused')::boolean, false, 'a first reservation creates a payment');
select is((select count(*)::int from public.payments), 1, 'one payment exists');
select is((select total_charged_cents || '/' || application_fee_cents || '/' || status from public.payments), '4500/161/requires_payment_method', 'absorb: payer pays $45.00; the application fee carries the estimated Stripe fee ($1.61) so the team nets base minus Stripe''s fee');
select is((select status from public.payment_requests where id = 'b1000000-0000-0000-0000-000000000001'), 'processing', 'the request is marked processing');
select is((select is_active from public.payment_items), true, 'its item is active');
select is((public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b1000000-0000-0000-0000-000000000001']::uuid[]) ->> 'reused')::boolean, true, 'reserving the same set again reuses the open payment');
select is((select count(*)::int from public.payments), 1, 'still one payment (no second intent)');
select throws_ok($$ select public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b1000000-0000-0000-0000-000000000001', 'b3000000-0000-0000-0000-000000000003']::uuid[]) $$, '23514', 'request_not_payable', 'a different set that includes a request already in a payment is refused');
select throws_ok($$ select public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b2000000-0000-0000-0000-000000000002']::uuid[]) $$, '42501', 'not_authorized', 'paying another family''s request is refused');
select throws_ok($$ select public.svc_reserve_payment('a1111111-1111-1111-1111-111111111111', array['b3000000-0000-0000-0000-000000000003']::uuid[]) $$, '42501', 'not_authorized', 'staff cannot pay');
select throws_ok($$ select public.svc_reserve_payment('a7777777-7777-7777-7777-777777777777', array['b3000000-0000-0000-0000-000000000003']::uuid[]) $$, '42501', 'not_authorized', 'a 13+ player cannot pay');
select throws_ok($$ select public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b1000000-0000-0000-0000-000000000001', 'b4000000-0000-0000-0000-000000000004']::uuid[]) $$, '23514', 'mixed_checkout', 'mixed fee terms cannot share a payment');
select lives_ok($$ select public.svc_attach_payment_intent((select id from public.payments), 'pi_Reserve1') $$, 'the intent id can be attached');
select lives_ok($$ select public.svc_attach_payment_intent((select id from public.payments), 'pi_Reserve1') $$, 'attaching the same id again is a no-op');
select throws_ok($$ select public.svc_attach_payment_intent((select id from public.payments), 'pi_Other') $$, '23505', 'payment_intent_conflict', 'a different id cannot replace it');
select lives_ok($$ select public.svc_release_payment((select id from public.payments)) $$, 'release is ignored once an intent exists');
select is((select status from public.payments), 'requires_payment_method', 'so the payment is untouched');
-- Creation failure path: a reservation with no intent is released and the request is free again.
select is((public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b3000000-0000-0000-0000-000000000003']::uuid[]) ->> 'reused')::boolean, false, 'another set reserves');
select lives_ok($$ select public.svc_release_payment((select id from public.payments where request_set_key = md5('b3000000-0000-0000-0000-000000000003'))) $$, 'release when Stripe creation failed');
select is((select status from public.payment_requests where id = 'b3000000-0000-0000-0000-000000000003'), 'unpaid', 'the request is unpaid again');
select is((select is_active from public.payment_items where payment_request_id = 'b3000000-0000-0000-0000-000000000003'), false, 'and its item is released');
-- pass_on with an Athleit charge: the team nets exactly the base.
select is((public.svc_reserve_payment('a2222222-2222-2222-2222-222222222222', array['b4000000-0000-0000-0000-000000000004']::uuid[]) ->> 'application_fee_cents')::int, 183, 'pass_on: application fee = Athleit charge 75c + service fee $1.08');
select is((select total_charged_cents - application_fee_cents from public.payments where request_set_key = md5('b4000000-0000-0000-0000-000000000004')), 2500, 'the team receives exactly the $25.00 base');

select * from finish();
rollback;
